 if($action==='history'){db()->prepare('INSERT INTO procedure_history(client_id,appointment_id,service_id,performed_at,professional_name,products_used,parameters_used,observations,next_recommendation,created_by) VALUES (?,?,?,?,?,?,?,?,?,?)')->execute([$id,$_POST['appointment_id']?:null,(int)$_POST['service_id'],$_POST['performed_at'],trim($_POST['professional_name'])?:null,$_POST['products_used']?:null,$_POST['parameters_used']?:null,$_POST['observations']?:null,$_POST['next_recommendation']?:null,$_SESSION['admin_id']]);$hid=(int)db()->lastInsertId();if(!empty($_FILES['photo']['name'])&&$_FILES['photo']['error']===UPLOAD_ERR_OK){$mime=(new finfo(FILEINFO_MIME_TYPE))->file($_FILES['photo']['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if($ext&&$_FILES['photo']['size']<=8*1024*1024){$name='client_'.$id.'_'.bin2hex(random_bytes(8)).'.'.$ext;$dest=__DIR__.'/../uploads/before_after/'.$name;move_uploaded_file($_FILES['photo']['tmp_name'],$dest);db()->prepare('INSERT INTO before_after_photos(client_id,procedure_id,photo_type,file_path,caption,consent_publish) VALUES (?,?,?,?,?,?)')->execute([$id,$hid,$_POST['photo_type']??'antes','uploads/before_after/'.$name,$_POST['caption']?:null,isset($_POST['consent_publish'])]);}}flash('ok','Procedimento registrado.');}
 header('Location: client.php?id='.$id);exit;}
