?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?= e($c['name']) ?> | PG Estética</title><link rel="stylesheet" href="../assets/css/style.css"></head><body class="admin-shell"><?php include '_nav.php'; ?><section><div class="container"><a href="clients.php">← Clientes</a><div class="admin-heading"><div><span class="eyebrow">prontuário</span><h1><?= e($c['name']) ?></h1></div><a class="btn btn-outline" target="_blank" href="https://wa.me/<?= e($c['phone']) ?>">Abrir WhatsApp</a></div><?php if($msg): ?><div class="notice"><?= e($msg) ?></div><?php endif; ?><div class="tabs-grid"><div class="panel"><h2>Cadastro</h2><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="client"><label>Nome</label><input name="name" value="<?= e($c['name']) ?>" required><div class="row"><div><label>WhatsApp</label><input name="phone" value="<?= e($c['phone']) ?>" required></div><div><label>E-mail</label><input type="email" name="email" value="<?= e($c['email']) ?>"></div></div><div class="row"><div><label>Nascimento</label><input type="date" name="birth_date" value="<?= e($c['birth_date']) ?>"></div><div><label>CPF</label><input name="cpf" value="<?= e($c['cpf']) ?>"></div></div><label>Endereço</label><input name="address" value="<?= e($c['address']) ?>"><label>Observações</label><textarea name="notes"><?= e($c['notes']) ?></textarea><button class="btn btn-primary" type="submit">Salvar cadastro</button></form></div><div class="panel"><h2>Ficha de anamnese</h2><p class="small muted">Dados clínicos devem ser acessados apenas por pessoal autorizado e tratados conforme a LGPD.</p><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="anamnesis"><label>Alergias</label><textarea name="allergies"><?= e($an['allergies']??'') ?></textarea><label>Medicamentos em uso</label><textarea name="medications"><?= e($an['medications']??'') ?></textarea><label>Condições de saúde</label><textarea name="medical_conditions"><?= e($an['medical_conditions']??'') ?></textarea><label>Cirurgias / procedimentos prévios</label><textarea name="surgeries"><?= e($an['surgeries']??'') ?></textarea><div class="checks"><label><input type="checkbox" name="pregnancy" <?= !empty($an['pregnancy'])?'checked':'' ?>> Gestante</label><label><input type="checkbox" name="pacemaker" <?= !empty($an['pacemaker'])?'checked':'' ?>> Marca-passo</label></div><label>Rotina de cuidados</label><textarea name="skincare_routine"><?= e($an['skincare_routine']??'') ?></textarea><label>Objetivos</label><textarea name="goals"><?= e($an['goals']??'') ?></textarea><label>Observações</label><textarea name="observations"><?= e($an['observations']??'') ?></textarea><label class="checkline"><input type="checkbox" name="consent" <?= !empty($an['consent'])?'checked':'' ?>> Consentimento registrado para armazenamento desta ficha.</label><button class="btn btn-primary" type="submit">Salvar anamnese</button></form></div></div><div class="panel"><h2>Registrar procedimento</h2><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="history"><div class="grid form-grid"><div><label>Serviço</label><select name="service_id" required><?php foreach($services as $s): ?><option value="<?= $s['id'] ?>"><?= e($s['name']) ?></option><?php endforeach; ?></select></div><div><label>Data/hora</label><input type="datetime-local" name="performed_at" value="<?= date('Y-m-d\TH:i') ?>" required></div><div><label>Profissional</label><input name="professional_name"></div><div><label>Agendamento relacionado</label><select name="appointment_id"><option value="">Nenhum</option><?php foreach($appointments as $a): ?><option value="<?= $a['id'] ?>"><?= date('d/m/Y',strtotime($a['appointment_date'])) ?> <?= substr($a['appointment_time'],0,5) ?> · <?= e($a['service_name']) ?></option><?php endforeach; ?></select></div></div><label>Produtos utilizados</label><textarea name="products_used"></textarea><label>Parâmetros/técnicas</label><textarea name="parameters_used"></textarea><label>Evolução e observações</label><textarea name="observations"></textarea><label>Próxima recomendação</label><textarea name="next_recommendation"></textarea><div class="row"><div><label>Foto de antes/depois</label><input type="file" name="photo" accept="image/jpeg,image/png,image/webp"></div><div><label>Tipo</label><select name="photo_type"><option value="antes">Antes</option><option value="depois">Depois</option></select></div></div><label>Legenda</label><input name="caption"><label class="checkline"><input type="checkbox" name="consent_publish"> Cliente autorizou uso/publicação desta foto</label><button class="btn btn-primary">Registrar procedimento</button></form></div><div class="two-col"><div class="panel"><h2>Histórico de procedimentos</h2><?php foreach($history as $h): ?><div class="history-item"><strong><?= e($h['service_name']) ?></strong><span><?= date('d/m/Y H:i',strtotime($h['performed_at'])) ?></span><?php if($h['professional_name']): ?><small>Profissional: <?= e($h['professional_name']) ?></small><?php endif; ?><p><?= nl2br(e($h['observations'])) ?></p></div><?php endforeach; ?></div><div class="panel"><h2>Fotos</h2><div class="photo-grid"><?php foreach($photos as $p): ?><figure><img src="../<?= e($p['file_path']) ?>" alt="<?= e($p['photo_type']) ?>"><figcaption><span class="badge"><?= e($p['photo_type']) ?></span> <?= e($p['caption']) ?></figcaption></figure><?php endforeach; ?></div><h2>Pacotes</h2><?php foreach($packs as $p): ?><p><strong><?= e($p['package_name']) ?></strong> · <?= e($p['status']) ?> · validade <?= $p['expires_at']?date('d/m/Y',strtotime($p['expires_at'])):'—' ?></p><?php endforeach; ?></div></div></div></section></body></html>
